-- JH Motors: los 12 autos de ejemplo del diseño (sin fotos), para ver la web con stock.
-- Pegar en Supabase → SQL Editor → Run. Se pueden correr de nuevo: si el auto ya existe (mismo slug), no se duplica.
-- Para sacarlos cuando se carguen los autos reales (borra SOLO estos 12):
--   delete from public.autos where concesionaria = 'jh-motors' and slug in ('ford-ranger-xlt-3-2-4x4-2020', 'fiat-cronos-drive-1-3-2022', 'peugeot-208-allure-1-6-2022', 'nissan-versa-advance-1-6-cvt-2022', 'chevrolet-onix-plus-premier-1-0-turbo-2023', 'renault-kwid-intens-1-0-2023', 'suzuki-swift-glx-1-2-2021', 'toyota-hilux-srv-2-8-4x4-2021', 'volkswagen-t-cross-highline-1-4-tsi-2022', 'hyundai-creta-limited-1-6-2021', 'byd-yuan-pro-gl-2024', 'byd-dolphin-gs-100-electrico-2024');
on conflict (concesionaria, slug) do nothing;
